import math
def priority(task, state, k=1.0, m=2.0, c=0.5, g=1e12):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    slack = task.due - state.now - est
    tier = m if task.tenant == 'premium' else 1.0
    if slack <= c * mean:
        return g - task.due - (tier - 1.0) * mean + 1e-6 / est
    return tier * task.weight / est * math.exp(-max(0.0, slack) / max(k * mean, 1e-6))

import math
def priority(task, state, b=0.5, m=2.0, c=0.0, g=1e15):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    slack = task.due - state.now - est
    wait = state.now - task.release
    tier = m if task.tenant == 'premium' else 1.0
    if slack < 0.0:
        return g - task.due + b * wait / est + c * (tier - 1.0)
    return -slack / est + b * wait / est + c * (tier - 1.0)

