import math
def priority(task, state, th=1.0, k=1.0, m=2.0, a=0.5, b=0.25):
    e = max(task.estimated_runtime, 1e-6)
    now = state.now
    mean = max(state.mean_est, 1e-6)
    slack = task.due - now - e
    tier = m if task.tenant == 'premium' else 1.0
    w = max(task.weight, 1e-6)
    wait = max(0.0, now - task.release)
    load = state.queue_work / max(state.capacity * mean, 1e-6)
    base = tier * w / e * math.exp(-max(0.0, slack) / (k * mean))
    if slack < 0.0:
        base += 1e5 * (1.0 + (-slack) / e)
    else:
        base += b / max(slack + e, 1e-6)
    base += a * wait / max(e, 1e-6)
    if load < th:
        return tier / e + 0.01 * base + b / max(task.due - now, 1e-6)
    else:
        return base + b * (-slack) / e

