def priority(task, state, late_penalty=1e9, premium_bonus=0.0, risk_boost=0.0, risk_window=2.0):
    now = state.now
    est = max(task.estimated_runtime, 1e-6)
    due = task.due
    score = -due
    if task.tenant == 'premium':
        score += premium_bonus
    if now >= due:
        score -= late_penalty
    else:
        slack = due - now - est
        if slack < 0.0:
            mean = max(state.mean_est, 1e-6)
            risk = min(-slack, risk_window * mean)
            score += risk_boost * risk / mean
    return score

def priority(task, state, late_penalty=1e12, rescue_boost=1.0, near_due_boost=0.0, near_window=2.0, premium_bonus=0.0, map_bonus=0.0, reduce_bonus=0.0, join_bonus=0.0, other_bonus=0.0, age=0.0):
    now = state.now
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    due = task.due
    score = -due
    if task.tenant == 'premium':
        score += premium_bonus
    if task.task_type == 'map':
        score += map_bonus
    elif task.task_type == 'reduce':
        score += reduce_bonus
    elif task.task_type == 'join':
        score += join_bonus
    else:
        score += other_bonus
    if now >= due:
        score -= late_penalty
    else:
        slack = due - now - est
        if slack < 0.0:
            score += rescue_boost
        elif slack < near_window * mean:
            denom = max(near_window * mean, 1e-6)
            score += near_due_boost * (1.0 - slack / denom)
    score += age * (now - task.release) / mean
    return score

