    now = state.now
    slack = task.due - now - est
    wait = max(0.0, now - task.release)
    tier = m if task.tenant == 'premium' else 1.0
    cores = max(task.resource_need, 1e-6)
    atc = max(task.weight, 1e-6) / est * math.exp(-max(0.0, slack) / max(k * mean_est, 1e-6))
    age = 1.0 + b * wait / est
    load = state.queue_work / max(state.capacity * mean_est, 1e-6)
    if load > th:
        return tier * max(task.weight, 1e-6) / max(est ** p, 1e-6) * math.exp(-max(0.0, slack) / max(k * mean_est, 1e-6)) * age / max(cores ** r, 1e-6)
    else:
