def priority(task, state, k=0.5, q=0.3, b=0.15, h=1.0, r=0.1, m=1.5, tm=1.0, tr=1.0, tj=1.0, to=1.0):
    est = max(task.estimated_runtime, 1e-6)
    now = state.now
    qdelay = q * state.queue_work / max(state.capacity, 1e-6)
    remaining = task.due - now - qdelay
    cr = remaining / est
    scale = max(k, 1e-6)
    if cr >= 0.0:
        urgency = math.exp(-cr / scale)
    else:
        late = -cr
        urgency = 1.0 + h * late / max(1.0 + late, 1e-6)
    if task.task_type == 'map':
