    else:
        type_factor = to
    tier = m if task.tenant == 'premium' else 1.0
    wait = max(0.0, now - task.release)
    age = 1.0 + b * wait / est
    cores = max(task.resource_need, 1e-6)
    return tier * type_factor * max(task.weight, 1e-6) / est * urgency * age / max(cores ** r, 1e-6)

