import math
def priority(task, state, qth=1.0, k=0.5, m=1.5, alpha=0.7, b=0.1, guard=1e6):
    est = max(task.estimated_runtime, 1e-6)
    now = state.now
    mean = max(state.mean_est, 1e-6)
    slack = task.due - now - est
    wait = max(0.0, now - task.release)
    congestion = state.queue_work / max(state.capacity * mean, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    if congestion >= qth:
        if slack <= 0.0:
            return tier * guard * (1.0 + wait / est) / est
        deadline_den = max(slack, 1e-6) + max(alpha * est, 1e-6)
        return tier * (1.0 + task.weight) / deadline_den * (1.0 + b * wait / est)
    else:
        den = max(k * mean, 1e-6)
        u = math.exp(-max(0.0, slack) / den)
        near = m if (task.tenant == 'premium' and slack <= mean) else 1.0
        return near * task.weight / est * u * (1.0 + b * wait / est)

