import math
def priority(task, state, h=1.0, d=0.45, g=20.0, k=0.5, a=0.1, m=1.8, p=0.4,
             tmap=1.0, treduce=1.05, tjoin=0.95, tother=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    slack = task.due - state.now - est
    base = task.weight / est

    if slack < 0.0:
        score = base * math.exp(max(-50.0, min(50.0, slack / (d * mean))))
    elif slack <= h * mean:
        score = g + (h * mean - slack) / (mean + est) + base
    else:
        score = base * math.exp(max(-50.0, min(50.0, -slack / (k * mean))))

    wait = state.now - task.release
    score += a * wait / (est + mean)

    x = (slack - h * mean) / max(p * mean, 1e-6)
    risk = 1.0 / (1.0 + math.exp(max(-50.0, min(50.0, x))))
    if task.tenant == 'premium':
        tier = 1.0 + (m - 1.0) * risk
    else:
        tier = 1.0

    if task.task_type == 'map':
        tf = tmap
    elif task.task_type == 'reduce':
        tf = treduce
    elif task.task_type == 'join':
        tf = tjoin
    else:
        tf = tother

    return tier * tf * score

