import math
def priority(task, state, m=1.0, age=0.2, spt=0.01, tol=0.0, B=1e12):
    now = state.now
    est = max(task.estimated_runtime, 1e-6)
    wait = now - task.release
    slack = task.due - now - est
    boost = (m - 1.0) * max(state.mean_est, 1.0) if task.tenant == 'premium' else 0.0
    if slack < -tol:
        return -B - est * max(task.resource_need, 1e-6)
    return -task.due + boost + age * wait / est + spt / est

