import math
def priority(task, state, horizon=5.0, p=0.5, q=0.3, tier_m=2.0, aging=0.1, doom=3.0, map_m=1.0, reduce_m=1.0, join_m=1.0, other_m=1.0, weight_m=0.0):
    e = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    cores = max(task.resource_need, 1e-6)
    slack = task.due - state.now - e
    if slack <= 0.0:
        urgency = 1.0 / (1.0 + (-slack) / max(doom * mean, 1e-6))
    else:
        urgency = max(0.0, 1.0 - slack / max(horizon * mean, 1e-6))
    if task.task_type == 'map':
        tm = map_m
    elif task.task_type == 'reduce':
        tm = reduce_m
    elif task.task_type == 'join':
        tm = join_m
    else:
        tm = other_m
    tier = tier_m if task.tenant == 'premium' else 1.0
    if weight_m != 0.0:
        wt = max(task.weight, 1e-6) ** weight_m
    else:
        wt = 1.0
    size = max((e ** p) * (cores ** q), 1e-6)
    wait = max(state.now - task.release, 0.0)
    age = aging * wait / mean
    return tier * tm * wt * urgency / size + age

