    scale = max(state.mean_est, 1e-6)
    need = max(task.resource_need, 1e-6)
    wait = max(0.0, state.now - task.release)
    delay = c * state.queue_work / max(state.capacity, 1e-6)
    raw_slack = task.due - state.now - est
    eff_slack = raw_slack - delay
    if raw_slack >= 0.0:
